export default function App() {
    const [inputText, setInputText] = useState('');
    const [outputText, setOutputText] = useState('');
    const [sourceLang, setSourceLang] = useState<LanguageCode>('Vietnamese');
    const [targetLang, setTargetLang] = useState<LanguageCode>('English');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [voice, setVoice] = useState<VoiceType>('female');
    const [isReadingInput, setIsReadingInput] = useState(false);
    const [isReadingOutput, setIsReadingOutput] = useState(false);
    const [analysis, setAnalysis] = useState<TranslationAnalysis | null>(null);
    const [pronunciation, setPronunciation] = useState<{score: number, feedback: string} | null>(null);

    const [isRecording, setIsRecording] = useState(false);
    const [isTranscribing, setIsTranscribing] = useState(false);
    const mediaRecorderRef = useRef<MediaRecorder | null>(null);
    const audioChunksRef = useRef<Blob[]>([]);
    const audioContextRef = useRef<AudioContext | null>(null);

    const getAudioContext = () => {
        if (!audioContextRef.current || audioContextRef.current.state === 'closed') {
             audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        return audioContextRef.current;
    }

    const handleTranslate = useCallback(async () => {
        if (!inputText.trim()) return;
        setLoading(true);
        setError(null);
        setAnalysis(null);

        try {
            const translation = await translateText(inputText, sourceLang, targetLang);
            setOutputText(translation);

            // Background analysis for better learning
            const insights = await analyzeTranslation(inputText, sourceLang, targetLang, translation);
            setAnalysis(insights);
        } catch (err) {
            setError("Lỗi khi xử lý bản dịch.");
        } finally {
            setLoading(false);
        }
    }, [inputText, sourceLang, targetLang]);

    const handleReadAloud = async (text: string, type: 'input' | 'output') => {
        if (!text.trim()) return;
        type === 'input' ? setIsReadingInput(true) : setIsReadingOutput(true);

        const audioData = await generateSpeech(text, voice);
        if (audioData) {
            try {
                const ctx = getAudioContext();
                const binaryString = atob(audioData);
                const bytes = new Uint8Array(binaryString.length);
                for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);

                const dataInt16 = new Int16Array(bytes.buffer);
                const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
                const channelData = buffer.getChannelData(0);
                for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;

                const source = ctx.createBufferSource();
                source.buffer = buffer;
                source.connect(ctx.destination);
                source.start();
            } catch (e) { console.error(e); }
        }
        type === 'input' ? setIsReadingInput(false) : setIsReadingOutput(false);
    };

    const startRecording = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            const mediaRecorder = new MediaRecorder(stream);
            mediaRecorderRef.current = mediaRecorder;
            audioChunksRef.current = [];
            mediaRecorder.ondataavailable = (e) => e.data.size > 0 && audioChunksRef.current.push(e.data);

            mediaRecorder.onstop = async () => {
                const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
                setIsTranscribing(true);
                try {
                    const reader = new FileReader();
                    reader.readAsDataURL(audioBlob);
                    reader.onloadend = async () => {
                        const base64 = (reader.result as string).split(',')[1];
                        const result = await transcribeAudio(base64, 'audio/webm', sourceLang);
                        setInputText(prev => prev ? prev + ' ' + result.text : result.text);
                        setPronunciation({ score: result.score, feedback: result.feedback });
                    };
                } catch (err) { setError("Lỗi chuyển giọng nói."); }
                finally { setIsTranscribing(false); stream.getTracks().forEach(t => t.stop()); }
            };
            mediaRecorder.start();
            setIsRecording(true);
            setPronunciation(null);
        } catch (err) { setError("Không thể truy cập micro."); }
    };

    return (
        <div className="min-h-screen bg-gray-100 dark:bg-gray-900 text-gray-900 dark:text-gray-200 p-4 sm:p-8">
            <div className="max-w-5xl mx-auto">
                <header className="text-center mb-10">
                    <h1 className="text-4xl font-extrabold text-blue-600 dark:text-blue-400">Gemini Smart Learning</h1>
                    <p className="text-gray-500 mt-2">Dịch thuật & Phân tích ngôn ngữ thông minh</p>
                </header>

                <main className="bg-white dark:bg-gray-800 shadow-xl rounded-3xl p-6 sm:p-8">
                    <div className="grid grid-cols-1 md:grid-cols-[1fr,auto,1fr] gap-4 items-start">
                        {/* Input */}
                        <div className="flex flex-col gap-2">
                            <select 
                                value={sourceLang} 
                                onChange={(e) => setSourceLang(e.target.value as LanguageCode)}
                                className="bg-gray-50 dark:bg-gray-700 p-3 rounded-xl border-none focus:ring-2 ring-blue-500"
                            >
                                {LANGUAGES.map(l => <option key={l.code} value={l.code}>{l.name}</option>)}
                            </select>
                            <div className="relative group">
                                <textarea
                                    value={inputText}
                                    onChange={(e) => setInputText(e.target.value)}
                                    className="w-full h-64 p-4 rounded-2xl bg-gray-50 dark:bg-gray-700/50 border-none focus:ring-2 ring-blue-500 resize-none text-lg"
                                    placeholder="Nhập nội dung hoặc nhấn micro để nói..."
                                />
                                <div className="absolute bottom-4 right-4 flex gap-2">
                                    <button 
                                        onClick={() => isRecording ? mediaRecorderRef.current?.stop() : startRecording()}
                                        className={`p-3 rounded-full shadow-lg transition-all ${isRecording ? 'bg-red-500 text-white animate-pulse' : 'bg-white dark:bg-gray-600 hover:scale-110'}`}
                                    >
                                        {isRecording ? <StopIcon /> : <MicrophoneIcon />}
                                    </button>
                                    <button onClick={() => handleReadAloud(inputText, 'input')} className="p-3 bg-white dark:bg-gray-600 rounded-full shadow-lg hover:scale-110">
                                        {isReadingInput ? <div className="animate-spin h-5 w-5 border-2 border-blue-500 rounded-full border-t-transparent" /> : <SpeakerIcon />}
                                    </button>
                                </div>
                                {isTranscribing && <div className="absolute inset-0 bg-white/80 dark:bg-gray-800/80 rounded-2xl flex items-center justify-center font-medium">Đang xử lý giọng nói...</div>}
                            </div>

                            {pronunciation && (
                                <div className="animate-slideIn mt-2 p-3 bg-green-50 dark:bg-green-900/20 border border-green-100 dark:border-green-800 rounded-xl">
                                    <div className="flex items-center gap-2">
                                        <div className={`text-xl font-bold ${pronunciation.score > 80 ? 'text-green-600' : 'text-yellow-600'}`}>{pronunciation.score}%</div>
                                        <div className="text-xs text-gray-600 dark:text-gray-400">{pronunciation.feedback}</div>
                                    </div>
                                </div>
                            )}
                        </div>

                        {/* Swap */}
                        <button 
                            onClick={() => {
                                const tempText = inputText;
                                const tempLang = sourceLang;
                                setInputText(outputText);
                                setOutputText(tempText);
                                setSourceLang(targetLang);
                                setTargetLang(tempLang);
                            }}
                            className="p-3 self-center mt-12 rounded-full bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 hover:rotate-180 transition-all duration-500"
                        >
                            <SwapIcon />
                        </button>

                        {/* Output */}
                        <div className="flex flex-col gap-2">
                            <select 
                                value={targetLang} 
                                onChange={(e) => setTargetLang(e.target.value as LanguageCode)}
                                className="bg-gray-50 dark:bg-gray-700 p-3 rounded-xl border-none focus:ring-2 ring-blue-500"
                            >
                                {LANGUAGES.map(l => <option key={l.code} value={l.code}>{l.name}</option>)}
                            </select>
                            <div className="relative">
                                <textarea
                                    value={outputText}
                                    readOnly
                                    className="w-full h-64 p-4 rounded-2xl bg-blue-50/50 dark:bg-blue-900/10 border-none text-lg text-blue-900 dark:text-blue-100"
                                    placeholder="Bản dịch sẽ xuất hiện tại đây..."
                                />
                                {loading && <div className="absolute inset-0 bg-white/50 dark:bg-gray-800/50 flex items-center justify-center"><div className="animate-spin h-10 w-10 border-4 border-blue-500 rounded-full border-t-transparent" /></div>}
                                <div className="absolute bottom-4 right-4">
                                    <button onClick={() => handleReadAloud(outputText, 'output')} className="p-3 bg-white dark:bg-gray-600 rounded-full shadow-lg hover:scale-110">
                                        {isReadingOutput ? <div className="animate-spin h-5 w-5 border-2 border-blue-500 rounded-full border-t-transparent" /> : <SpeakerIcon />}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="mt-8 flex flex-col items-center">
                        <div className="flex gap-4 mb-6">
                            <button onClick={() => setVoice('female')} className={`px-6 py-2 rounded-full font-medium transition-all ${voice === 'female' ? 'bg-blue-600 text-white shadow-lg' : 'bg-gray-100 dark:bg-gray-700 text-gray-500'}`}>Giọng Nữ</button>
                            <button onClick={() => setVoice('male')} className={`px-6 py-2 rounded-full font-medium transition-all ${voice === 'male' ? 'bg-blue-600 text-white shadow-lg' : 'bg-gray-100 dark:bg-gray-700 text-gray-500'}`}>Giọng Nam</button>
                        </div>
                        <button 
                            onClick={handleTranslate}
                            disabled={loading || !inputText.trim()}
                            className="w-full sm:w-auto px-16 py-4 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-2xl shadow-xl transition-all transform hover:scale-105 active:scale-95 disabled:opacity-50"
                        >
                            {loading ? 'Đang phân tích...' : 'Dịch & Học tập'}
                        </button>
                    </div>

                    {analysis && <AnalysisSection analysis={analysis} />}
                    {error && <div className="mt-6 p-4 bg-red-50 dark:bg-red-900/20 text-red-600 rounded-xl text-center font-medium border border-red-100 dark:border-red-800">{error}</div>}
                </main>

                <footer className="text-center mt-8 text-gray-400 text-sm">
                    &copy; 2024 Gemini AI Language Learning. Được xây dựng để giúp bạn giỏi ngoại ngữ hơn.
                </footer>
            </div>

            <style>{`
                @keyframes fadeIn { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
                @keyframes slideIn { from { opacity: 0; transform: translateX(-10px); } to { opacity: 1; transform: translateX(0); } }
                .animate-fadeIn { animation: fadeIn 0.3s ease-out forwards; }
                .animate-slideIn { animation: slideIn 0.3s ease-out forwards; }
            `}</style>
        </div>
    );
}

export type LanguageCode = 'Vietnamese' | 'English' | 'Korean' | 'Simplified Chinese' | 'Cantonese';

export interface Language {
  code: LanguageCode;
  name: string;
}

export type VoiceType = 'female' | 'male';

export interface VocabularyItem {
  word: string;
  definition: string;
  example: string;
  visualPrompt: string;
  imageUrl?: string;
}

export interface TranslationAnalysis {
  grammar: string;
  variations: {
    style: string;
    text: string;
  }[];
  vocabulary: VocabularyItem[];
}

export interface TranscriptionResult {
  text: string;
  score: number;
  feedback: string;
}

import { GoogleGenAI, Modality, Type } from "@google/genai";
import { LanguageCode, VoiceType, TranslationAnalysis, TranscriptionResult } from '../types';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

const PREBUILT_VOICES = {
    female: 'Kore',
    male: 'Puck',
};

export async function translateText(
  text: string,
  sourceLang: LanguageCode,
  targetLang: LanguageCode
): Promise<string> {
  if (!text.trim()) {
    return "";
  }

  try {
    const prompt = `Translate the following text from ${sourceLang} to ${targetLang}. 
    Provide only the translated text, without any additional explanations, introductions, or formatting.

    Text to translate:
    \`\`\`
    ${text}
    \`\`\``;

    const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt
    });

    return response.text.trim();
  } catch (error) {
    console.error("Error translating text:", error);
    return "An error occurred during translation.";
  }
}

export async function generateVocabImage(prompt: string): Promise<string | null> {
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: {
                parts: [{ text: `A clean, educational, 3D clay-style or high-quality illustration of: ${prompt}. Minimal background, vibrant colors, suitable for a language learning app.` }],
            },
            config: {
                imageConfig: {
                    aspectRatio: "1:1"
                }
            }
        });

        for (const part of response.candidates[0].content.parts) {
            if (part.inlineData) {
                return `data:image/png;base64,${part.inlineData.data}`;
            }
        }
        return null;
    } catch (error) {
        console.error("Error generating image:", error);
        return null;
    }
}

export async function analyzeTranslation(
    text: string,
    sourceLang: string,
    targetLang: string,
    translatedText: string
): Promise<TranslationAnalysis | null> {
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Analyze this translation for a language learner. 
            Source (${sourceLang}): "${text}"
            Target (${targetLang}): "${translatedText}"

            Provide:
            1. Grammar explanation (concise).
            2. Variations (Formal, Informal, Slang).
            3. 3-4 Key vocabulary words with:
               - definition
               - one example sentence
               - a very short "visualPrompt" in English (2-5 words) to generate a clear image of this word/concept.`,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        grammar: { type: Type.STRING },
                        variations: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    style: { type: Type.STRING },
                                    text: { type: Type.STRING }
                                },
                                required: ["style", "text"]
                            }
                        },
                        vocabulary: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    word: { type: Type.STRING },
                                    definition: { type: Type.STRING },
                                    example: { type: Type.STRING },
                                    visualPrompt: { type: Type.STRING }
                                },
                                required: ["word", "definition", "example", "visualPrompt"]
                            }
                        }
                    },
                    required: ["grammar", "variations", "vocabulary"]
                }
            }
        });

        return JSON.parse(response.text);
    } catch (error) {
        console.error("Error analyzing translation:", error);
        return null;
    }
}

export async function transcribeAudio(
  audioBase64: string,
  mimeType: string,
  language: string
): Promise<TranscriptionResult> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          {
            inlineData: {
              data: audioBase64,
              mimeType: mimeType,
            },
          },
          {
            text: `Transcribe the speech in this audio exactly. The language is ${language}. 
            Also, rate the pronunciation clarity from 0 to 100 and provide one brief sentence of feedback for improvement.`,
          },
        ],
      },
      config: {
          responseMimeType: "application/json",
          responseSchema: {
              type: Type.OBJECT,
              properties: {
                  text: { type: Type.STRING },
                  score: { type: Type.NUMBER },
                  feedback: { type: Type.STRING }
              },
              required: ["text", "score", "feedback"]
          }
      }
    });

    const result = JSON.parse(response.text);
    return result;
  } catch (error) {
    console.error("Error transcribing audio:", error);
    throw error;
  }
}

export async function generateSpeech(
  text: string,
  voice: VoiceType
): Promise<string | null> {
  if (!text.trim()) return null;

  try {
    const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text }] }],
        config: {
            responseModalities: [Modality.AUDIO],
            speechConfig: {
                voiceConfig: {
                  prebuiltVoiceConfig: { voiceName: PREBUILT_VOICES[voice] },
                },
            },
        },
    });

    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
  } catch (error) {
    console.error("Error generating speech:", error);
    return null;
  }
}

