export default function App() {
    const [inputText, setInputText] = useState('');
    const [outputText, setOutputText] = useState('');
    const [sourceLang, setSourceLang] = useState<LanguageCode>('Vietnamese');
    const [targetLang, setTargetLang] = useState<LanguageCode>('English');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [voice, setVoice] = useState<VoiceType>('female');
    const [isReadingInput, setIsReadingInput] = useState(false);
    const [isReadingOutput, setIsReadingOutput] = useState(false);
    const [analysis, setAnalysis] = useState<TranslationAnalysis | null>(null);
    const [pronunciation, setPronunciation] = useState<{score: number, feedback: string} | null>(null);

    const [isRecording, setIsRecording] = useState(false);
    const [isTranscribing, setIsTranscribing] = useState(false);
    const mediaRecorderRef = useRef<MediaRecorder | null>(null);
    const audioChunksRef = useRef<Blob[]>([]);
    const audioContextRef = useRef<AudioContext | null>(null);

    const getAudioContext = () => {
        if (!audioContextRef.current || audioContextRef.current.state === 'closed') {
             audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        return audioContextRef.current;
    }

    // Effect to clear analysis when switching to non-English target
    useEffect(() => {
        if (targetLang !== 'English') {
            setAnalysis(null);
            setPronunciation(null);
        }
    }, [targetLang]);

    // Effect to generate images for vocabulary in background
    useEffect(() => {
        if (targetLang === 'English' && analysis && analysis.vocabulary) {
            analysis.vocabulary.forEach(async (item, index) => {
                if (!item.imageUrl) {
                    const url = await generateVocabImage(item.visualPrompt);
                    if (url) {
                        setAnalysis(prev => {
                            if (!prev) return null;
                            const newVocab = [...prev.vocabulary];
                            newVocab[index] = { ...newVocab[index], imageUrl: url };
                            return { ...prev, vocabulary: newVocab };
                        });
                    }
                }
            });
        }
    }, [analysis?.vocabulary?.length, targetLang]);

    const handleTranslate = useCallback(async () => {
        if (!inputText.trim()) return;
        setLoading(true);
        setError(null);
        setAnalysis(null);

        try {
            const translation = await translateText(inputText, sourceLang, targetLang);
            setOutputText(translation);

            // Background analysis ONLY if target language is English
            if (targetLang === 'English') {
                const insights = await analyzeTranslation(inputText, sourceLang, targetLang, translation);
                setAnalysis(insights);
            }
        } catch (err) {
            setError("Lỗi khi xử lý bản dịch.");
        } finally {
            setLoading(false);
        }
    }, [inputText, sourceLang, targetLang]);

    const handleReadAloud = async (text: string, type: 'input' | 'output') => {
        if (!text.trim()) return;
        type === 'input' ? setIsReadingInput(true) : setIsReadingOutput(true);

        const audioData = await generateSpeech(text, voice);
        if (audioData) {
            try {
                const ctx = getAudioContext();
                const binaryString = atob(audioData);
                const bytes = new Uint8Array(binaryString.length);
                for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);

                const dataInt16 = new Int16Array(bytes.buffer);
                const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
                const channelData = buffer.getChannelData(0);
                for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;

                const source = ctx.createBufferSource();
                source.buffer = buffer;
                source.connect(ctx.destination);
                source.start();
            } catch (e) { console.error(e); }
        }
        type === 'input' ? setIsReadingInput(false) : setIsReadingOutput(false);
    };

    const startRecording = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            const mediaRecorder = new MediaRecorder(stream);
            mediaRecorderRef.current = mediaRecorder;
            audioChunksRef.current = [];
            mediaRecorder.ondataavailable = (e) => e.data.size > 0 && audioChunksRef.current.push(e.data);

            mediaRecorder.onstop = async () => {
                const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
                setIsTranscribing(true);
                try {
                    const reader = new FileReader();
                    reader.readAsDataURL(audioBlob);
                    reader.onloadend = async () => {
                        const base64 = (reader.result as string).split(',')[1];
                        const result = await transcribeAudio(base64, 'audio/webm', sourceLang);
                        setInputText(prev => prev ? prev + ' ' + result.text : result.text);
                        // Pronunciation score only makes sense for learning context (usually English in this app)
                        if (targetLang === 'English') {
                            setPronunciation({ score: result.score, feedback: result.feedback });
                        }
                    };
                } catch (err) { setError("Lỗi chuyển giọng nói."); }
                finally { setIsTranscribing(false); stream.getTracks().forEach(t => t.stop()); }
            };
            mediaRecorder.start();
            setIsRecording(true);
            setPronunciation(null);
        } catch (err) { setError("Không thể truy cập micro."); }
    };

    return (
        <div className="min-h-screen bg-gray-100 dark:bg-gray-900 text-gray-900 dark:text-gray-200 p-4 sm:p-8">
            <div className="max-w-5xl mx-auto">
                <header className="text-center mb-10">
                    <h1 className="text-4xl font-extrabold text-blue-600 dark:text-blue-400 tracking-tight">Gemini Vision Learner</h1>
                    <p className="text-gray-500 mt-2 font-medium">Học ngoại ngữ thông minh & Dịch thuật tốc độ</p>
                </header>

                <main className="bg-white dark:bg-gray-800 shadow-2xl rounded-[2.5rem] p-6 sm:p-10 border border-gray-100 dark:border-gray-700">
                    <div className="grid grid-cols-1 md:grid-cols-[1fr,auto,1fr] gap-6 items-start">
                        {/* Input */}
                        <div className="flex flex-col gap-3">
                            <label className="text-xs font-bold text-gray-400 uppercase ml-2">Từ</label>
                            <select 
                                value={sourceLang} 
                                onChange={(e) => setSourceLang(e.target.value as LanguageCode)}
                                className="bg-gray-50 dark:bg-gray-700 p-4 rounded-2xl border-none focus:ring-2 ring-blue-500 font-semibold text-gray-700 dark:text-gray-200"
                            >
                                {LANGUAGES.map(l => <option key={l.code} value={l.code}>{l.name}</option>)}
                            </select>
                            <div className="relative group">
                                <textarea
                                    value={inputText}
                                    onChange={(e) => setInputText(e.target.value)}
                                    className="w-full h-72 p-6 rounded-3xl bg-gray-50 dark:bg-gray-700/50 border-none focus:ring-2 ring-blue-500 resize-none text-xl leading-relaxed transition-all"
                                    placeholder="Nhập nội dung..."
                                />
                                <div className="absolute bottom-4 right-4 flex gap-3">
                                    <button 
                                        onClick={() => isRecording ? mediaRecorderRef.current?.stop() : startRecording()}
                                        className={`p-4 rounded-full shadow-2xl transition-all ${isRecording ? 'bg-red-500 text-white scale-110' : 'bg-white dark:bg-gray-600 hover:scale-110 active:scale-95 text-blue-600 dark:text-blue-400'}`}
                                    >
                                        {isRecording ? <StopIcon /> : <MicrophoneIcon isRecording={isRecording} />}
                                    </button>
                                    <button onClick={() => handleReadAloud(inputText, 'input')} className="p-4 bg-white dark:bg-gray-600 text-blue-600 dark:text-blue-400 rounded-full shadow-2xl hover:scale-110 active:scale-95">
                                        {isReadingInput ? <div className="animate-spin h-5 w-5 border-2 border-blue-500 rounded-full border-t-transparent" /> : <SpeakerIcon />}
                                    </button>
                                </div>
                                {isTranscribing && <div className="absolute inset-0 bg-white/90 dark:bg-gray-800/90 rounded-3xl flex items-center justify-center font-bold text-blue-600 animate-pulse">Đang nhận diện...</div>}
                            </div>

                            {pronunciation && targetLang === 'English' && (
                                <div className="animate-slideIn p-4 bg-green-50 dark:bg-green-900/20 border border-green-100 dark:border-green-800 rounded-2xl flex items-center gap-4">
                                    <div className={`text-2xl font-black ${pronunciation.score > 80 ? 'text-green-600' : 'text-yellow-600'}`}>{pronunciation.score}</div>
                                    <div className="flex-1">
                                        <div className="text-[10px] font-bold text-green-600 dark:text-green-400 uppercase tracking-widest">Phát âm</div>
                                        <div className="text-sm text-gray-700 dark:text-gray-300 font-medium">{pronunciation.feedback}</div>
                                    </div>
                                </div>
                            )}
                        </div>

                        {/* Swap */}
                        <button 
                            onClick={() => {
                                const tempText = inputText;
                                const tempLang = sourceLang;
                                setInputText(outputText);
                                setOutputText(tempText);
                                setSourceLang(targetLang);
                                setTargetLang(tempLang);
                            }}
                            className="p-4 self-center mt-12 rounded-full bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 hover:rotate-180 transition-all duration-700 shadow-lg border border-blue-100 dark:border-blue-900/50"
                        >
                            <SwapIcon />
                        </button>

                        {/* Output */}
                        <div className="flex flex-col gap-3">
                            <label className="text-xs font-bold text-gray-400 uppercase ml-2">Sang</label>
                            <select 
                                value={targetLang} 
                                onChange={(e) => setTargetLang(e.target.value as LanguageCode)}
                                className="bg-gray-50 dark:bg-gray-700 p-4 rounded-2xl border-none focus:ring-2 ring-blue-500 font-semibold text-gray-700 dark:text-gray-200"
                            >
                                {LANGUAGES.map(l => <option key={l.code} value={l.code}>{l.name}</option>)}
                            </select>
                            <div className="relative">
                                <textarea
                                    value={outputText}
                                    readOnly
                                    className="w-full h-72 p-6 rounded-3xl bg-blue-50/30 dark:bg-blue-900/10 border-none text-xl leading-relaxed text-blue-900 dark:text-blue-100 font-medium"
                                    placeholder="Kết quả..."
                                />
                                {loading && <div className="absolute inset-0 bg-white/60 dark:bg-gray-800/60 rounded-3xl flex items-center justify-center"><div className="animate-spin h-12 w-12 border-4 border-blue-500 rounded-full border-t-transparent" /></div>}
                                <div className="absolute bottom-4 right-4">
                                    <button onClick={() => handleReadAloud(outputText, 'output')} className="p-4 bg-white dark:bg-gray-600 text-blue-600 dark:text-blue-400 rounded-full shadow-2xl hover:scale-110 active:scale-95">
                                        {isReadingOutput ? <div className="animate-spin h-5 w-5 border-2 border-blue-500 rounded-full border-t-transparent" /> : <SpeakerIcon />}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="mt-10 flex flex-col items-center">
                        <div className="flex gap-3 mb-8 bg-gray-50 dark:bg-gray-700 p-1 rounded-full">
                            <button onClick={() => setVoice('female')} className={`px-8 py-2.5 rounded-full text-sm font-bold transition-all ${voice === 'female' ? 'bg-white dark:bg-gray-600 text-blue-600 shadow-sm' : 'text-gray-400'}`}>Nữ (Kore)</button>
                            <button onClick={() => setVoice('male')} className={`px-8 py-2.5 rounded-full text-sm font-bold transition-all ${voice === 'male' ? 'bg-white dark:bg-gray-600 text-blue-600 shadow-sm' : 'text-gray-400'}`}>Nam (Puck)</button>
                        </div>
                        <button 
                            onClick={handleTranslate}
                            disabled={loading || !inputText.trim()}
                            className="w-full sm:w-auto px-20 py-5 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-black rounded-3xl shadow-[0_20px_50px_rgba(37,_99,_235,_0.3)] transition-all transform hover:scale-[1.02] active:scale-95 disabled:opacity-50 text-lg uppercase tracking-wider"
                        >
                            {loading ? 'Đang dịch...' : (targetLang === 'English' ? 'Dịch & Phân tích chuyên sâu' : 'Dịch nhanh')}
                        </button>
                    </div>

                    {targetLang === 'English' && analysis && <AnalysisSection analysis={analysis} />}
                    {error && <div className="mt-8 p-5 bg-red-50 dark:bg-red-900/20 text-red-600 rounded-2xl text-center font-bold border border-red-100 dark:border-red-800">{error}</div>}
                </main>

                <footer className="text-center mt-12 mb-8">
                    <p className="text-gray-400 text-xs font-bold uppercase tracking-[0.2em] mb-2">Powered by Gemini AI</p>
                    <p className="text-gray-500 text-sm">&copy; 2024 Gemini AI Learner. Ưu tiên học tiếng Anh chuyên sâu.</p>
                </footer>
            </div>

            <style>{`
                @keyframes fadeIn { from { opacity: 0; transform: scale(0.98); } to { opacity: 1; transform: scale(1); } }
                @keyframes slideIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
                .animate-fadeIn { animation: fadeIn 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
                .animate-slideIn { animation: slideIn 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
                textarea::-webkit-scrollbar { width: 8px; }
                textarea::-webkit-scrollbar-track { background: transparent; }
                textarea::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.1); border-radius: 10px; }
            `}</style>
        </div>
    );
}

export type LanguageCode = 'Vietnamese' | 'English' | 'Korean' | 'Simplified Chinese' | 'Cantonese';

export interface Language {
  code: LanguageCode;
  name: string;
}

export type VoiceType = 'female' | 'male';

export interface VocabularyItem {
  word: string;
  definition: string;
  example: string;
  visualPrompt: string;
  imageUrl?: string;
}

export interface TranslationAnalysis {
  grammar: string;
  variations: {
    style: string;
    text: string;
  }[];
  vocabulary: VocabularyItem[];
}

export interface TranscriptionResult {
  text: string;
  score: number;
  feedback: string;
}

export interface Scenario {
  id: string;
  name: string;
  icon: string;
  description: string;
  initialPrompt: string;
}

export interface ChatMessage {
  role: 'ai' | 'user';
  text: string;
  feedback?: {
    isCorrect: boolean;
    explanation: string;
    suggestion: string;
  };
}

export interface PracticeTurnResponse {
  aiResponse: string;
  feedback: {
    isCorrect: boolean;
    explanation: string;
