import { translateText, generateSpeech, transcribeAudio, analyzeTranslation, generateVocabImage, getPracticeResponse } from './services/geminiService';

const SwapIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6"><path strokeLinecap="round" strokeLinejoin="round" d="M7.5 21L3 16.5m0 0L7.5 12M3 16.5h13.5m0-13.5L21 7.5m0 0L16.5 12M21 7.5H7.5" /></svg>
);
const SpeakerIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M19.114 5.636a9 9 0 0 1 0 12.728M16.463 8.288a5.25 5.25 0 0 1 0 7.424M6.75 8.25l4.72-4.72a.75.75 0 0 1 1.28.53v15.88a.75.75 0 0 1-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 0 1 2.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75Z" /></svg>
);
const MicrophoneIcon = ({ isRecording }: { isRecording?: boolean }) => (
    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className={`w-5 h-5 ${isRecording ? 'text-red-500 animate-pulse' : ''}`}><path strokeLinecap="round" strokeLinejoin="round" d="M12 18.75a6 6 0 0 0 6-6v-1.5m-6 7.5a6 6 0 0 1-6-6v-1.5m6 7.5v3.75m-3.75 0h7.5M12 15.75a3 3 0 0 1-3-3V4.5a3 3 0 1 1 6 0v8.25a3 3 0 0 1-3 3Z" /></svg>
);
const StopIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" fill="currentColor" viewBox="0 0 24 24" className="w-5 h-5 text-red-600"><rect x="6" y="6" width="12" height="12" rx="2" /></svg>
);

const ConversationTab = ({ voice }: { voice: VoiceType }) => {
    const [scenario, setScenario] = useState<Scenario | null>(null);
    const [messages, setMessages] = useState<ChatMessage[]>([]);
    const [inputText, setInputText] = useState('');
    const [loading, setLoading] = useState(false);
    const [isRecording, setIsRecording] = useState(false);
    const mediaRecorderRef = useRef<MediaRecorder | null>(null);
    const audioChunksRef = useRef<Blob[]>([]);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const scrollToBottom = () => messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    useEffect(() => { scrollToBottom(); }, [messages]);

    const startScenario = async (s: Scenario) => {
        setScenario(s);
        setLoading(true);
        setMessages([]);
        // Initial AI prompt
        const response = await getPracticeResponse([], s.initialPrompt, "Hello, let's start.");
        if (response) {
            setMessages([{ role: 'ai', text: response.aiResponse }]);
            handleTTS(response.aiResponse);
        }
        setLoading(false);
    };

    const handleSendMessage = async (text: string) => {
        if (!text.trim() || !scenario || loading) return;
        const newUserMsg: ChatMessage = { role: 'user', text };
        setMessages(prev => [...prev, newUserMsg]);
        setInputText('');
        setLoading(true);

        const response = await getPracticeResponse(messages, scenario.initialPrompt, text);
        if (response) {
            const updatedUserMsg: ChatMessage = { ...newUserMsg, feedback: response.feedback };
            setMessages(prev => {
                const next = [...prev];
                next[next.length - 1] = updatedUserMsg;
                return [...next, { role: 'ai', text: response.aiResponse }];
            });
            handleTTS(response.aiResponse);
        }
        setLoading(false);
    };

    const handleTTS = async (text: string) => {
        const audioData = await generateSpeech(text, voice);
        if (audioData) {
            const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            const binaryString = atob(audioData);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
            const dataInt16 = new Int16Array(bytes.buffer);
            const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
            buffer.getChannelData(0).set(Array.from(dataInt16).map(v => v / 32768.0));
            const source = ctx.createBufferSource();
            source.buffer = buffer;
            source.connect(ctx.destination);
            source.start();
        }
    };

    const startRecording = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            const recorder = new MediaRecorder(stream);
            mediaRecorderRef.current = recorder;
            audioChunksRef.current = [];
            recorder.ondataavailable = e => audioChunksRef.current.push(e.data);
            recorder.onstop = async () => {
                const blob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
                const reader = new FileReader();
                reader.readAsDataURL(blob);
                reader.onloadend = async () => {
                    const base64 = (reader.result as string).split(',')[1];
                    const trans = await transcribeAudio(base64, 'audio/webm', 'English');
                    handleSendMessage(trans.text);
                };
            };
            recorder.start();
            setIsRecording(true);
        } catch (e) { alert("Microphone access denied."); }
    };

    if (!scenario) {
        return (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 animate-fadeIn">
                {SCENARIOS.map(s => (
                    <button 
                        key={s.id} 
                        onClick={() => startScenario(s)}
                        className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-sm hover:shadow-xl hover:scale-[1.02] transition-all text-left border border-gray-100 dark:border-gray-700"
                    >
                        <div className="text-4xl mb-4">{s.icon}</div>
                        <h3 className="font-bold text-lg text-gray-900 dark:text-white">{s.name}</h3>
                        <p className="text-sm text-gray-500 mt-1">{s.description}</p>
                    </button>
                ))}
            </div>
        );
    }

    return (
        <div className="flex flex-col h-[600px] animate-fadeIn">
            <div className="flex items-center justify-between mb-4 px-2">
                <button onClick={() => setScenario(null)} className="text-sm font-bold text-blue-600 flex items-center gap-1">
                    ← Đổi phối cảnh
                </button>
                <span className="text-sm font-medium text-gray-400">{scenario.name}</span>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-6 bg-gray-50 dark:bg-gray-900/50 rounded-3xl mb-4 scrollbar-hide">
                {messages.map((m, i) => (
                    <div key={i} className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                        <div className={`max-w-[85%] p-4 rounded-2xl ${m.role === 'user' ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-100 rounded-tl-none shadow-sm'}`}>
                            {m.text}
                            {m.role === 'ai' && (
                                <button onClick={() => handleTTS(m.text)} className="ml-2 inline-block opacity-50 hover:opacity-100">
                                    <SpeakerIcon />
                                </button>
                            )}
                        </div>
                        {m.feedback && (
                            <div className={`mt-2 max-w-[80%] p-3 rounded-xl text-xs border ${m.feedback.isCorrect ? 'bg-green-50 border-green-200 text-green-700' : 'bg-yellow-50 border-yellow-200 text-yellow-700'}`}>
                                <div className="font-bold mb-1">{m.feedback.isCorrect ? '✓ Chính xác!' : '💡 Gợi ý sửa lỗi:'}</div>
                                <div>{m.feedback.explanation}</div>
                                {!m.feedback.isCorrect && <div className="mt-1 font-mono italic">Suggest: {m.feedback.suggestion}</div>}
                            </div>
                        )}
                    </div>
                ))}
                {loading && <div className="flex justify-start animate-pulse"><div className="bg-gray-200 dark:bg-gray-700 h-10 w-24 rounded-2xl rounded-tl-none"></div></div>}
                <div ref={messagesEndRef} />
            </div>

            <div className="flex gap-2">
                <input 
                    value={inputText}
                    onChange={e => setInputText(e.target.value)}
                    onKeyDown={e => e.key === 'Enter' && handleSendMessage(inputText)}
                    placeholder="Nhập câu trả lời của bạn..."
                    className="flex-1 p-4 rounded-2xl bg-white dark:bg-gray-800 border-none shadow-sm focus:ring-2 ring-blue-500"
                />
                <button 
                    onClick={() => isRecording ? mediaRecorderRef.current?.stop() : startRecording()}
                    className={`p-4 rounded-2xl shadow-sm transition-all ${isRecording ? 'bg-red-500 text-white animate-pulse' : 'bg-white dark:bg-gray-800 text-blue-600'}`}
                >
                    {isRecording ? <StopIcon /> : <MicrophoneIcon />}
                </button>
                <button 
                    onClick={() => handleSendMessage(inputText)}
                    disabled={!inputText.trim() || loading}
                    className="p-4 bg-blue-600 text-white rounded-2xl shadow-lg disabled:opacity-50"
                >
                    Gửi
                </button>
            </div>
        </div>
    );
};

const DictionaryTab = ({ voice }: { voice: VoiceType }) => {
    const [inputText, setInputText] = useState('');
    const [outputText, setOutputText] = useState('');
    const [sourceLang, setSourceLang] = useState<LanguageCode>('Vietnamese');
    const [targetLang, setTargetLang] = useState<LanguageCode>('English');
    const [loading, setLoading] = useState(false);
    const [analysis, setAnalysis] = useState<TranslationAnalysis | null>(null);

    useEffect(() => { if (targetLang !== 'English') setAnalysis(null); }, [targetLang]);

    useEffect(() => {
        if (targetLang === 'English' && analysis?.vocabulary) {
            analysis.vocabulary.forEach(async (item, index) => {
                if (!item.imageUrl) {
                    const url = await generateVocabImage(item.visualPrompt);
                    if (url) {
                        setAnalysis(prev => {
                            if (!prev) return null;
                            const newVocab = [...prev.vocabulary];
                            newVocab[index] = { ...newVocab[index], imageUrl: url };
                            return { ...prev, vocabulary: newVocab };
                        });
                    }
                }
            });
        }
    }, [analysis?.vocabulary?.length, targetLang]);

    const handleTranslate = async () => {
        if (!inputText.trim()) return;
        setLoading(true);
        setAnalysis(null);
        try {
            const trans = await translateText(inputText, sourceLang, targetLang);
            setOutputText(trans);
            if (targetLang === 'English') {
                const insights = await analyzeTranslation(inputText, sourceLang, targetLang, trans);
                setAnalysis(insights);
            }
        } catch (e) {} finally { setLoading(false); }
    };

    return (
        <div className="animate-fadeIn">
            <div className="grid grid-cols-1 md:grid-cols-[1fr,auto,1fr] gap-4">
                <div className="space-y-2">
                    <select value={sourceLang} onChange={e => setSourceLang(e.target.value as LanguageCode)} className="w-full p-3 rounded-xl bg-gray-50 dark:bg-gray-700 border-none font-bold">
                        {LANGUAGES.map(l => <option key={l.code} value={l.code}>{l.name}</option>)}
                    </select>
                    <textarea value={inputText} onChange={e => setInputText(e.target.value)} className="w-full h-48 p-4 rounded-2xl bg-gray-50 dark:bg-gray-700/50 border-none resize-none text-lg" placeholder="Nhập văn bản..." />
                </div>
                <button onClick={() => { setSourceLang(targetLang); setTargetLang(sourceLang); setInputText(outputText); setOutputText(inputText); }} className="self-center mt-8 p-3 rounded-full bg-blue-50 dark:bg-blue-900/30 text-blue-600"><SwapIcon /></button>
                <div className="space-y-2">
                    <select value={targetLang} onChange={e => setTargetLang(e.target.value as LanguageCode)} className="w-full p-3 rounded-xl bg-gray-50 dark:bg-gray-700 border-none font-bold">
                        {LANGUAGES.map(l => <option key={l.code} value={l.code}>{l.name}</option>)}
                    </select>
                    <div className="relative">
                        <textarea value={outputText} readOnly className="w-full h-48 p-4 rounded-2xl bg-blue-50/30 dark:bg-blue-900/10 border-none resize-none text-lg" placeholder="Kết quả..." />
                        {loading && <div className="absolute inset-0 flex items-center justify-center bg-white/50 dark:bg-gray-800/50 rounded-2xl"><div className="animate-spin h-8 w-8 border-4 border-blue-500 rounded-full border-t-transparent" /></div>}
                    </div>
                </div>
            </div>
            <div className="mt-6 text-center">
                <button onClick={handleTranslate} disabled={loading || !inputText.trim()} className="px-12 py-4 bg-blue-600 text-white font-bold rounded-2xl shadow-xl hover:scale-[1.02] active:scale-95 transition-all">
                    {loading ? 'Đang xử lý...' : 'Dịch thuật'}
                </button>
            </div>
            {analysis && (
                <div className="mt-8 p-6 bg-blue-50 dark:bg-gray-800/50 rounded-3xl border border-blue-100 dark:border-blue-900/30">
                    <h3 className="font-bold text-blue-800 dark:text-blue-300 mb-4">Phân tích học tập</h3>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                        {analysis.vocabulary.map((v, i) => (
                            <div key={i} className="bg-white dark:bg-gray-800 p-3 rounded-2xl shadow-sm">
                                <div className="h-32 bg-gray-100 dark:bg-gray-700 rounded-xl mb-3 overflow-hidden">
                                    {v.imageUrl ? <img src={v.imageUrl} className="w-full h-full object-cover" /> : <div className="flex items-center justify-center h-full text-[10px] text-gray-400">Đang tạo ảnh...</div>}
                                </div>
                                <div className="font-bold text-gray-900 dark:text-white uppercase text-sm">{v.word}</div>
                                <div className="text-xs text-blue-600 mt-1">{v.definition}</div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

