// Quick Translator Component
const MiniTranslator = () => {
    const [qInput, setQInput] = useState('');
    const [qOutput, setQOutput] = useState('');
    const [loading, setLoading] = useState(false);

    const handleQuickTranslate = async () => {
        if (!qInput.trim()) return;
        setLoading(true);
        try {
            const res = await translateText(qInput, 'English', 'Vietnamese');
            setQOutput(res);
        } catch (e) {
            setQOutput('Lỗi tra từ');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="mt-6 p-4 bg-gray-50 dark:bg-gray-900/40 rounded-2xl border border-dashed border-blue-200 dark:border-blue-900/40">
            <h4 className="text-[10px] font-bold text-blue-500 uppercase tracking-widest mb-2 flex items-center gap-1">
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 5h12M9 3v2m1.048 9.5a18.022 18.022 0 0 1-3.827-5.802M12 9l-1.516-3.5a18.022 18.022 0 0 0-3.827 5.802M3 11l4.5 4.5L12 11" /></svg>
                Tra từ điển nhanh (EN → VI)
            </h4>
            <div className="flex gap-2">
                <input 
                    value={qInput}
                    onChange={e => setQInput(e.target.value)}
                    onKeyDown={e => e.key === 'Enter' && handleQuickTranslate()}
                    className="flex-1 text-xs p-2.5 rounded-xl bg-white dark:bg-gray-800 border-none shadow-sm focus:ring-1 ring-blue-400"
                    placeholder="Nhập từ cần tra..."
                />
                <button 
                    onClick={handleQuickTranslate}
                    disabled={loading}
                    className="px-4 bg-blue-500 text-white text-xs font-bold rounded-xl hover:bg-blue-600 transition-colors"
                >
                    {loading ? '...' : 'Tra'}
                </button>
            </div>
            {qOutput && (
                <div className="mt-2 p-2.5 bg-blue-50/50 dark:bg-blue-900/20 rounded-xl text-xs text-blue-800 dark:text-blue-300 font-medium animate-fadeIn">
                    {qOutput}
                </div>
            )}
        </div>
    );
};

const ConversationTab = ({ voice, state, setState }: { voice: VoiceType, state: any, setState: any }) => {
    const [isRecording, setIsRecording] = useState(false);
    const mediaRecorderRef = useRef<MediaRecorder | null>(null);
    const audioChunksRef = useRef<Blob[]>([]);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const scrollToBottom = () => messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    useEffect(() => { scrollToBottom(); }, [state.messages]);

    const startScenario = async (s: Scenario) => {
        setState({ ...state, scenario: s, loading: true, messages: [] });
        const response = await getPracticeResponse([], s.initialPrompt, "Hello, let's start.");
        if (response) {
            setState({ 
                ...state, 
                scenario: s, 
                loading: false, 
                messages: [{ role: 'ai', text: response.aiResponse }] 
            });
            handleTTS(response.aiResponse);
        } else {
            setState({ ...state, scenario: s, loading: false });
        }
    };

    const handleSendMessage = async (text: string) => {
        if (!text.trim() || !state.scenario || state.loading) return;
        const newUserMsg: ChatMessage = { role: 'user', text };
        const updatedMessages = [...state.messages, newUserMsg];
        setState({ ...state, messages: updatedMessages, inputText: '', loading: true });

        const response = await getPracticeResponse(state.messages, state.scenario.initialPrompt, text);
        if (response) {
            const updatedUserMsgWithFeedback: ChatMessage = { ...newUserMsg, feedback: response.feedback };
            setState({ 
                ...state, 
                messages: [...state.messages, updatedUserMsgWithFeedback, { role: 'ai', text: response.aiResponse }],
                inputText: '',
                loading: false 
            });
            handleTTS(response.aiResponse);
        } else {
            setState({ ...state, loading: false });
        }
    };

    const handleTTS = async (text: string) => {
        const audioData = await generateSpeech(text, voice);
        if (audioData) {
            const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            const binaryString = atob(audioData);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
            const dataInt16 = new Int16Array(bytes.buffer);
            const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
            buffer.getChannelData(0).set(Array.from(dataInt16).map(v => v / 32768.0));
            const source = ctx.createBufferSource();
            source.buffer = buffer;
            source.connect(ctx.destination);
            source.start();
        }
    };

    const startRecording = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            const recorder = new MediaRecorder(stream);
            mediaRecorderRef.current = recorder;
            audioChunksRef.current = [];
            recorder.ondataavailable = e => audioChunksRef.current.push(e.data);
            recorder.onstop = async () => {
                const blob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
                const reader = new FileReader();
                reader.readAsDataURL(blob);
                reader.onloadend = async () => {
                    const base64 = (reader.result as string).split(',')[1];
                    const trans = await transcribeAudio(base64, 'audio/webm', 'English');
                    handleSendMessage(trans.text);
                };
            };
            recorder.start();
            setIsRecording(true);
        } catch (e) { alert("Microphone access denied."); }
    };

    if (!state.scenario) {
        return (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 animate-fadeIn">
                {SCENARIOS.map(s => (
                    <button 
                        key={s.id} 
                        onClick={() => startScenario(s)}
                        className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-sm hover:shadow-xl hover:scale-[1.02] transition-all text-left border border-gray-100 dark:border-gray-700"
                    >
                        <div className="text-4xl mb-4">{s.icon}</div>
                        <h3 className="font-bold text-lg text-gray-900 dark:text-white">{s.name}</h3>
                        <p className="text-sm text-gray-500 mt-1">{s.description}</p>
                    </button>
                ))}
            </div>
        );
    }

    return (
        <div className="flex flex-col h-[700px] animate-fadeIn">
            <div className="flex items-center justify-between mb-4 px-2">
                <button onClick={() => setState({ ...state, scenario: null })} className="text-sm font-bold text-blue-600 flex items-center gap-1">
                    ← Đổi phối cảnh
                </button>
                <span className="text-sm font-medium text-gray-400">{state.scenario.name}</span>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-6 bg-gray-50 dark:bg-gray-900/50 rounded-3xl mb-4 scrollbar-hide border border-gray-100 dark:border-gray-800">
                {state.messages.map((m: ChatMessage, i: number) => (
                    <div key={i} className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                        <div className={`max-w-[85%] p-4 rounded-2xl ${m.role === 'user' ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-100 rounded-tl-none shadow-sm'}`}>
                            {m.text}
                            {m.role === 'ai' && (
                                <button onClick={() => handleTTS(m.text)} className="ml-2 inline-block opacity-50 hover:opacity-100">
                                    <SpeakerIcon />
                                </button>
                            )}
                        </div>
                        {m.feedback && (
                            <div className={`mt-2 max-w-[80%] p-3 rounded-xl text-xs border ${m.feedback.isCorrect ? 'bg-green-50 border-green-200 text-green-700' : 'bg-yellow-50 border-yellow-200 text-yellow-700'}`}>
                                <div className="font-bold mb-1">{m.feedback.isCorrect ? '✓ Chính xác!' : '💡 Gợi ý sửa lỗi:'}</div>
                                <div>{m.feedback.explanation}</div>
                                {!m.feedback.isCorrect && <div className="mt-1 font-mono italic">Suggest: {m.feedback.suggestion}</div>}
                            </div>
                        )}
                    </div>
                ))}
                {state.loading && <div className="flex justify-start animate-pulse"><div className="bg-gray-200 dark:bg-gray-700 h-10 w-24 rounded-2xl rounded-tl-none"></div></div>}
                <div ref={messagesEndRef} />
            </div>

            <div className="flex gap-2">
                <input 
                    value={state.inputText}
                    onChange={e => setState({ ...state, inputText: e.target.value })}
                    onKeyDown={e => e.key === 'Enter' && handleSendMessage(state.inputText)}
                    placeholder="Nhập câu trả lời của bạn..."
                    className="flex-1 p-4 rounded-2xl bg-white dark:bg-gray-800 border-none shadow-sm focus:ring-2 ring-blue-500"
                />
                <button 
                    onClick={() => isRecording ? mediaRecorderRef.current?.stop() : startRecording()}
                    className={`p-4 rounded-2xl shadow-sm transition-all ${isRecording ? 'bg-red-500 text-white animate-pulse' : 'bg-white dark:bg-gray-800 text-blue-600'}`}
                >
                    {isRecording ? <StopIcon /> : <MicrophoneIcon />}
                </button>
                <button 
                    onClick={() => handleSendMessage(state.inputText)}
                    disabled={!state.inputText.trim() || state.loading}
                    className="p-4 bg-blue-600 text-white rounded-2xl shadow-lg disabled:opacity-50"
                >
                    Gửi
                </button>
            </div>

            {/* INTEGRATED QUICK DICTIONARY */}
            <MiniTranslator />
        </div>
    );
};

const DictionaryTab = ({ voice, state, setState }: { voice: VoiceType, state: any, setState: any }) => {
    useEffect(() => { if (state.targetLang !== 'English') setState({ ...state, analysis: null }); }, [state.targetLang]);

    useEffect(() => {
        if (state.targetLang === 'English' && state.analysis?.vocabulary) {
            state.analysis.vocabulary.forEach(async (item: VocabularyItem, index: number) => {
                if (!item.imageUrl) {
                    const url = await generateVocabImage(item.visualPrompt);
                    if (url) {
                        const newVocab = [...state.analysis.vocabulary];
                        newVocab[index] = { ...newVocab[index], imageUrl: url };
                        setState({ ...state, analysis: { ...state.analysis, vocabulary: newVocab } });
                    }
                }
            });
        }
    }, [state.analysis?.vocabulary?.length, state.targetLang]);

    const handleTranslate = async () => {
        if (!state.inputText.trim()) return;
        setState({ ...state, loading: true, analysis: null });
        try {
            const trans = await translateText(state.inputText, state.sourceLang, state.targetLang);
            let insights = null;
            if (state.targetLang === 'English') {
                insights = await analyzeTranslation(state.inputText, state.sourceLang, state.targetLang, trans);
            }
            setState({ ...state, outputText: trans, analysis: insights, loading: false });
        } catch (e) {
            setState({ ...state, loading: false });
        }
    };

    return (
        <div className="animate-fadeIn">
            <div className="grid grid-cols-1 md:grid-cols-[1fr,auto,1fr] gap-4">
                <div className="space-y-2">
                    <select value={state.sourceLang} onChange={e => setState({ ...state, sourceLang: e.target.value as LanguageCode })} className="w-full p-3 rounded-xl bg-gray-50 dark:bg-gray-700 border-none font-bold">
                        {LANGUAGES.map(l => <option key={l.code} value={l.code}>{l.name}</option>)}
                    </select>
                    <textarea value={state.inputText} onChange={e => setState({ ...state, inputText: e.target.value })} className="w-full h-48 p-4 rounded-2xl bg-gray-50 dark:bg-gray-700/50 border-none resize-none text-lg" placeholder="Nhập văn bản..." />
                </div>
                <button 
                    onClick={() => setState({ 
                        ...state, 
                        sourceLang: state.targetLang, 
                        targetLang: state.sourceLang, 
                        inputText: state.outputText, 
                        outputText: state.inputText 
                    })} 
                    className="self-center mt-8 p-3 rounded-full bg-blue-50 dark:bg-blue-900/30 text-blue-600"
                >
                    <SwapIcon />
                </button>
                <div className="space-y-2">
                    <select value={state.targetLang} onChange={e => setState({ ...state, targetLang: e.target.value as LanguageCode })} className="w-full p-3 rounded-xl bg-gray-50 dark:bg-gray-700 border-none font-bold">
                        {LANGUAGES.map(l => <option key={l.code} value={l.code}>{l.name}</option>)}
                    </select>
                    <div className="relative">
                        <textarea value={state.outputText} readOnly className="w-full h-48 p-4 rounded-2xl bg-blue-50/30 dark:bg-blue-900/10 border-none resize-none text-lg" placeholder="Kết quả..." />
                        {state.loading && <div className="absolute inset-0 flex items-center justify-center bg-white/50 dark:bg-gray-800/50 rounded-2xl"><div className="animate-spin h-8 w-8 border-4 border-blue-500 rounded-full border-t-transparent" /></div>}
                    </div>
                </div>
            </div>
            <div className="mt-6 text-center">
                <button onClick={handleTranslate} disabled={state.loading || !state.inputText.trim()} className="px-12 py-4 bg-blue-600 text-white font-bold rounded-2xl shadow-xl hover:scale-[1.02] active:scale-95 transition-all">
                    {state.loading ? 'Đang xử lý...' : 'Dịch thuật'}
                </button>
            </div>
            {state.analysis && (
                <div className="mt-8 p-6 bg-blue-50 dark:bg-gray-800/50 rounded-3xl border border-blue-100 dark:border-blue-900/30">
                    <h3 className="font-bold text-blue-800 dark:text-blue-300 mb-4">Phân tích học tập</h3>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                        {state.analysis.vocabulary.map((v: VocabularyItem, i: number) => (
                            <div key={i} className="bg-white dark:bg-gray-800 p-3 rounded-2xl shadow-sm">
                                <div className="h-32 bg-gray-100 dark:bg-gray-700 rounded-xl mb-3 overflow-hidden">
                                    {v.imageUrl ? <img src={v.imageUrl} className="w-full h-full object-cover" /> : <div className="flex items-center justify-center h-full text-[10px] text-gray-400">Đang tạo ảnh...</div>}
                                </div>
                                <div className="font-bold text-gray-900 dark:text-white uppercase text-sm">{v.word}</div>
                                <div className="text-xs text-blue-600 mt-1">{v.definition}</div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

