const ConversationTab = ({ voice, state, setState }: { voice: VoiceType, state: any, setState: any }) => {
    const [isRecording, setIsRecording] = useState(false);
    const mediaRecorderRef = useRef<MediaRecorder | null>(null);
    const audioChunksRef = useRef<Blob[]>([]);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const scrollToBottom = () => messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    useEffect(() => { scrollToBottom(); }, [state.messages]);

    const startScenario = async (s: Scenario) => {
        setState({ ...state, scenario: s, loading: true, messages: [] });
        const response = await getPracticeResponse([], s.initialPrompt, "Hello, let's start.");
        if (response) {
            setState({ 
                ...state, 
                scenario: s, 
                loading: false, 
                messages: [{ role: 'ai', text: response.aiResponse }] 
            });
            handleTTS(response.aiResponse);
        } else {
            setState({ ...state, scenario: s, loading: false });
        }
    };

    const handleSendMessage = async (text: string) => {
        if (!text.trim() || !state.scenario || state.loading) return;
        const newUserMsg: ChatMessage = { role: 'user', text };
        const currentMessages = [...state.messages, newUserMsg];
        setState({ ...state, messages: currentMessages, inputText: '', loading: true });

        const response = await getPracticeResponse(state.messages, state.scenario.initialPrompt, text);
        if (response) {
            const updatedUserMsgWithFeedback: ChatMessage = { ...newUserMsg, feedback: response.feedback };
            setState({ 
                ...state, 
                messages: [...state.messages, updatedUserMsgWithFeedback, { role: 'ai', text: response.aiResponse }],
                inputText: '',
                loading: false 
            });
            handleTTS(response.aiResponse);
        } else {
            setState({ ...state, loading: false });
        }
    };

    const handleTTS = async (text: string) => {
        const audioData = await generateSpeech(text, voice);
        if (audioData) {
            const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            const binaryString = atob(audioData);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
            const dataInt16 = new Int16Array(bytes.buffer);
            const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
            buffer.getChannelData(0).set(Array.from(dataInt16).map(v => v / 32768.0));
            const source = ctx.createBufferSource();
            source.buffer = buffer;
            source.connect(ctx.destination);
            source.start();
        }
    };

    const startRecording = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            const recorder = new MediaRecorder(stream);
            mediaRecorderRef.current = recorder;
            audioChunksRef.current = [];
            recorder.ondataavailable = e => audioChunksRef.current.push(e.data);
            recorder.onstop = async () => {
                const blob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
                const reader = new FileReader();
                reader.readAsDataURL(blob);
                reader.onloadend = async () => {
                    const base64 = (reader.result as string).split(',')[1];
                    const trans = await transcribeAudio(base64, 'audio/webm', 'English');
                    handleSendMessage(trans.text);
                };
            };
            recorder.start();
            setIsRecording(true);
        } catch (e) { alert("Microphone access denied."); }
    };

    if (!state.scenario) {
        return (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 animate-fadeIn">
                {SCENARIOS.map(s => (
                    <button 
                        key={s.id} 
                        onClick={() => startScenario(s)}
                        className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-sm hover:shadow-xl hover:scale-[1.02] transition-all text-left border border-gray-100 dark:border-gray-700"
                    >
                        <div className="text-4xl mb-4">{s.icon}</div>
                        <h3 className="font-bold text-lg text-gray-900 dark:text-white">{s.name}</h3>
                        <p className="text-sm text-gray-500 mt-1">{s.description}</p>
                    </button>
                ))}
            </div>
        );
    }

    return (
        <div className="flex flex-col animate-fadeIn">
            <div className="flex items-center justify-between mb-4 px-2">
                <button onClick={() => setState({ ...state, scenario: null })} className="text-sm font-bold text-blue-600 flex items-center gap-1">
                    ← Đổi phối cảnh
                </button>
                <span className="text-sm font-black text-gray-400 uppercase tracking-widest">{state.scenario.name}</span>
            </div>

            <div className="h-[500px] overflow-y-auto p-4 space-y-6 bg-gray-50 dark:bg-gray-900/50 rounded-3xl mb-4 scrollbar-hide border border-gray-100 dark:border-gray-800 shadow-inner">
                {state.messages.map((m: ChatMessage, i: number) => (
                    <div key={i} className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'} animate-slideIn`}>
                        <div className={`max-w-[85%] p-4 rounded-2xl ${m.role === 'user' ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-100 rounded-tl-none shadow-sm'}`}>
                            {m.text}
                            {m.role === 'ai' && (
                                <button onClick={() => handleTTS(m.text)} className="ml-2 inline-block opacity-50 hover:opacity-100">
                                    <SpeakerIcon />
                                </button>
                            )}
                        </div>
                        {m.feedback && (
                            <div className={`mt-2 max-w-[80%] p-4 rounded-2xl text-xs border ${m.feedback.isCorrect ? 'bg-green-50 border-green-200 text-green-700' : 'bg-yellow-50 border-yellow-200 text-yellow-700 shadow-sm'}`}>
                                <div className="font-black mb-1 flex items-center gap-1">
                                    {m.feedback.isCorrect ? '✓ CHÍNH XÁC' : '💡 GỢI Ý CỦA GIÁO VIÊN:'}
                                </div>
                                <div className="leading-relaxed">{m.feedback.explanation}</div>
                                {!m.feedback.isCorrect && (
                                    <div className="mt-2 p-2 bg-white/50 dark:bg-black/10 rounded-lg font-medium">
                                        💡 Cách nói tốt hơn: <span className="text-blue-600 dark:text-blue-400 italic">"{m.feedback.suggestion}"</span>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                ))}
                {state.loading && <div className="flex justify-start animate-pulse"><div className="bg-gray-200 dark:bg-gray-700 h-10 w-24 rounded-2xl rounded-tl-none"></div></div>}
                <div ref={messagesEndRef} />
            </div>

            <div className="flex gap-2 mb-2">
                <input 
                    value={state.inputText}
                    onChange={e => setState({ ...state, inputText: e.target.value })}
                    onKeyDown={e => e.key === 'Enter' && handleSendMessage(state.inputText)}
                    placeholder="Nhập câu trả lời bằng tiếng Anh..."
                    className="flex-1 p-4 rounded-2xl bg-white dark:bg-gray-800 border-none shadow-sm focus:ring-2 ring-blue-500 font-medium"
                />
                <button 
                    onClick={() => isRecording ? mediaRecorderRef.current?.stop() : startRecording()}
                    className={`p-4 rounded-2xl shadow-sm transition-all ${isRecording ? 'bg-red-500 text-white animate-pulse' : 'bg-white dark:bg-gray-800 text-blue-600 hover:scale-105 active:scale-95'}`}
                >
                    {isRecording ? <StopIcon /> : <MicrophoneIcon />}
                </button>
                <button 
                    onClick={() => handleSendMessage(state.inputText)}
                    disabled={!state.inputText.trim() || state.loading}
                    className="px-6 bg-blue-600 text-white font-black rounded-2xl shadow-lg disabled:opacity-50 hover:bg-blue-700 transition-colors uppercase text-xs tracking-widest"
                >
                    Gửi
                </button>
            </div>

            {/* FULL MINI TRANSLATOR */}
            <FullMiniTranslator state={state} setState={setState} />
        </div>
    );
};

const DictionaryTab = ({ voice, state, setState }: { voice: VoiceType, state: any, setState: any }) => {
    useEffect(() => { if (state.targetLang !== 'English') setState({ ...state, analysis: null }); }, [state.targetLang]);

    useEffect(() => {
        if (state.targetLang === 'English' && state.analysis?.vocabulary) {
            state.analysis.vocabulary.forEach(async (item: VocabularyItem, index: number) => {
                if (!item.imageUrl) {
                    const url = await generateVocabImage(item.visualPrompt);
                    if (url) {
                        const newVocab = [...state.analysis.vocabulary];
                        newVocab[index] = { ...newVocab[index], imageUrl: url };
                        setState({ ...state, analysis: { ...state.analysis, vocabulary: newVocab } });
                    }
                }
            });
        }
    }, [state.analysis?.vocabulary?.length, state.targetLang]);

    const handleTranslate = async () => {
        if (!state.inputText.trim()) return;
        setState({ ...state, loading: true, analysis: null });
        try {
            const trans = await translateText(state.inputText, state.sourceLang, state.targetLang);
            let insights = null;
            if (state.targetLang === 'English') {
                insights = await analyzeTranslation(state.inputText, state.sourceLang, state.targetLang, trans);
            }
            setState({ ...state, outputText: trans, analysis: insights, loading: false });
        } catch (e) {
            setState({ ...state, loading: false });
        }
    };

    return (
        <div className="animate-fadeIn">
            <div className="grid grid-cols-1 md:grid-cols-[1fr,auto,1fr] gap-4">
                <div className="space-y-2">
                    <select value={state.sourceLang} onChange={e => setState({ ...state, sourceLang: e.target.value as LanguageCode })} className="w-full p-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-none font-bold text-gray-700 dark:text-gray-200">
