                        >
                            Dịch thuật
                        </button>
                        <button 
                            onClick={() => setActiveTab('practice')} 
                            className={`px-10 py-3 rounded-2xl text-sm font-black transition-all uppercase tracking-widest ${activeTab === 'practice' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}
