                <main className="bg-white dark:bg-gray-800 shadow-[0_40px_100px_rgba(0,0,0,0.08)] rounded-[3rem] p-6 sm:p-12 border border-gray-100 dark:border-gray-700 relative overflow-hidden">
                    <div className="mb-10 flex justify-end items-center gap-4">
