import { GoogleGenAI, Modality, Type } from "@google/genai";
import { LanguageCode, VoiceType, TranslationAnalysis, TranscriptionResult, PracticeTurnResponse, ChatMessage } from '../types';

/**
 * Initialize GoogleGenAI client.
 * Using process.env.API_KEY directly as per guidelines.
 */
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const PREBUILT_VOICES = {
    female: 'Kore',
    male: 'Puck',
};

// Basic Text Task: Summarization/Translation uses gemini-3-flash-preview
export async function translateText(
  text: string,
  sourceLang: LanguageCode,
  targetLang: LanguageCode
): Promise<string> {
  if (!text.trim()) return "";
  try {
    const prompt = `Translate the following text from ${sourceLang} to ${targetLang}. 
    Provide only the translated text.

    Text: ${text}`;
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
    });
    return response.text?.trim() || "Translation failed.";
  } catch (error) {
    console.error("Translation error:", error);
    return "An error occurred.";
  }
}

// Complex Text Task: Reasoning and Roleplay uses gemini-3-flash-preview
export async function getPracticeResponse(
    history: ChatMessage[],
    scenarioPrompt: string,
    userInput: string
): Promise<PracticeTurnResponse | null> {
    try {
        const historyContext = history.map(m => `${m.role === 'ai' ? 'AI' : 'User'}: ${m.text}`).join('\n');

        const systemInstruction = `You are an English teacher and conversation partner. 
        Context: ${scenarioPrompt}

        Rules:
        1. Evaluate the user's latest input for grammar, naturalness, and spelling.
        2. Provide feedback in Vietnamese: is it correct, what's the error, and a better way to say it.
        3. Respond as the character in the scenario to keep the conversation going in English.
        4. Keep your AI response concise and engaging.`;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `History:\n${historyContext}\nUser's new message: "${userInput}"`,
            config: {
                systemInstruction,
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        aiResponse: { type: Type.STRING, description: "Your next response in the roleplay (English)" },
                        feedback: {
                            type: Type.OBJECT,
                            properties: {
                                isCorrect: { type: Type.BOOLEAN },
                                explanation: { type: Type.STRING, description: "Brief explanation in Vietnamese about the user's grammar/style" },
                                suggestion: { type: Type.STRING, description: "A more natural/correct way to say it in English" }
                            },
                            required: ["isCorrect", "explanation", "suggestion"]
                        }
                    },
                    required: ["aiResponse", "feedback"]
                }
            }
        });

        const result = response.text;
        return result ? JSON.parse(result) : null;
    } catch (error) {
        console.error("Practice Error:", error);
        return null;
    }
}

// General Image Generation Task: uses gemini-2.5-flash-image
export async function generateVocabImage(prompt: string): Promise<string | null> {
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { parts: [{ text: `A clean illustration of: ${prompt}. Minimal background, high quality.` }] },
            config: { imageConfig: { aspectRatio: "1:1" } }
        });
        for (const part of response.candidates[0].content.parts) {
            if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
        }
        return null;
    } catch (error) { 
        console.error("Image generation error:", error);
        return null; 
    }
}

// Complex Text Task: Analysis uses gemini-3-flash-preview
export async function analyzeTranslation(
    text: string,
    sourceLang: string,
    targetLang: string,
    translatedText: string
): Promise<TranslationAnalysis | null> {
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Analyze translation from ${sourceLang} to ${targetLang}. 
            Source: "${text}"
            Target: "${translatedText}"`,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        grammar: { type: Type.STRING },
                        variations: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: { style: { type: Type.STRING }, text: { type: Type.STRING } },
                                required: ["style", "text"]
                            }
                        },
                        vocabulary: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    word: { type: Type.STRING },
                                    definition: { type: Type.STRING },
                                    example: { type: Type.STRING },
                                    visualPrompt: { type: Type.STRING }
                                },
                                required: ["word", "definition", "example", "visualPrompt"]
                            }
                        }
                    },
                    required: ["grammar", "variations", "vocabulary"]
                }
            }
        });
        const result = response.text;
        return result ? JSON.parse(result) : null;
    } catch (error) { 
        console.error("Analysis error:", error);
        return null; 
    }
}

// Basic Text/Audio Task: Transcription uses gemini-3-flash-preview (multimodal)
export async function transcribeAudio(
  audioBase64: string,
  mimeType: string,
  language: string
): Promise<TranscriptionResult> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [{ inlineData: { data: audioBase64, mimeType } }, { text: `Transcribe this ${language} audio. Rate pronunciation 0-100.` }],
      },
      config: {
          responseMimeType: "application/json",
          responseSchema: {
              type: Type.OBJECT,
              properties: {
                  text: { type: Type.STRING },
                  score: { type: Type.NUMBER },
                  feedback: { type: Type.STRING }
              },
              required: ["text", "score", "feedback"]
          }
      }
    });
    const result = response.text;
    if (!result) throw new Error("Empty response from model");
    return JSON.parse(result);
  } catch (error) { 
    console.error("Transcription error:", error);
    throw error; 
  }
}

// Text-to-speech task: uses gemini-2.5-flash-preview-tts
export async function generateSpeech(text: string, voice: VoiceType): Promise<string | null> {
  if (!text.trim()) return null;
  try {
    const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text }] }],
        config: {
            responseModalities: [Modality.AUDIO],
            speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: PREBUILT_VOICES[voice] } } },
        },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
  } catch (error) { 
    console.error("TTS error:", error);
    return null; 
  }
}

